use serde_yaml_ng::Value;
use std::{
    fs,
    path::Path,
    process::{Command, Output},
};

fn write(root: &Path, path: &str, body: &str) {
    let file = root.join(path);
    fs::create_dir_all(file.parent().unwrap()).unwrap();
    fs::write(file, body).unwrap();
}
fn fixture(source: &Path, sidebar: &str) {
    write(
        source,
        "docusaurus.config.js",
        "module.exports = {title: 'Autogenerated'};",
    );
    write(
        source,
        "sidebars.js",
        &format!("module.exports = {{docs: {sidebar}}};"),
    );
}
fn convert(source: &Path, out: &Path, dry_run: bool) -> Output {
    let mut command = Command::new(env!("CARGO_BIN_EXE_zel"));
    command.arg("convert").arg(source).arg("--out").arg(out);
    if dry_run {
        command.arg("--dry-run");
    }
    command.output().unwrap()
}
fn success(output: Output) -> String {
    assert!(
        output.status.success(),
        "{}\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    String::from_utf8(output.stdout).unwrap()
}
fn nav(out: &Path) -> Value {
    let value: Value =
        serde_yaml_ng::from_str(&fs::read_to_string(out.join("01-guide/_sidebar.yaml")).unwrap())
            .unwrap();
    value["nav"].clone()
}
fn names(nav: &Value) -> Vec<&str> {
    nav.as_sequence()
        .unwrap()
        .iter()
        .map(|item| item.as_str().or_else(|| item["label"].as_str()).unwrap())
        .collect()
}

#[test]
fn nested_categories_follow_positions_prefixes_and_labels_without_changing_sources() {
    let temp = tempfile::tempdir().unwrap();
    let source = temp.path().join("source");
    let out = temp.path().join("out");
    fixture(&source, "[{type: 'autogenerated', dirName: '.'}]");
    for (file, raw) in [
        ("02-first.md", "---\nsidebar_position: -1\n---\n# First"),
        ("10-last.md", "# Last"),
        ("2026-11-04.md", "# Date"),
        ("z.md", "# Unpositioned"),
        (
            "03-Guides/index.mdx",
            "---\nsidebar_position: 99\nsidebar_label: Overview\n---\n# Guide overview\n\n[Start](01-Start.md)",
        ),
        (
            "03-Guides/01-Start.md",
            "---\nid: beginning\nsidebar_label: First lesson\n---\n# Start",
        ),
        (
            "03-Guides/02-Part.md",
            "---\nsidebar_label: Second lesson\n---\n# Part",
        ),
        ("03-Guides/10-Deep/README.md", "# Deep overview"),
        ("07-Another/07-Another.md", "# Another overview"),
        ("03-Guides/draft.md", "---\ndraft: true\n---\n# Draft"),
        ("03-Guides/hidden.md", "---\nunlisted: true\n---\n# Hidden"),
        ("_partial.mdx", "---\nnot a complete document"),
        ("_partials/snippet.mdx", "---\nunclosed"),
        (".private/notes.md", "---\nunclosed"),
    ] {
        write(&source, &format!("docs/{file}"), raw);
    }
    let category = r#"{"label":"Guides...","position":2.5,"collapsed":false}"#;
    write(&source, "docs/03-Guides/_category_.json", category);
    write(
        &source,
        "docs/03-Guides/10-Deep/_category_.yml",
        "label: Nested\nposition: 0.5\n",
    );
    write(
        &source,
        "docs/07-Another/_category_.yaml",
        "label: Another\nposition: 1.5\n",
    );
    let report = success(convert(&source, &out, false));
    let nav = nav(&out);
    assert_eq!(
        names(&nav),
        [
            "02-first",
            "Another",
            "Guides...",
            "10-last",
            "2026-11-04",
            "z"
        ]
    );
    assert_eq!(nav[1]["page"], "07-Another/07-Another");
    assert_eq!(
        names(&nav[2]["items"]),
        ["Overview", "Nested", "First lesson", "Second lesson"]
    );
    assert_eq!(nav[2]["items"][1]["page"], "03-Guides/10-Deep/README");
    assert!(report.contains("category fields not mapped: collapsed"));
    assert!(report.contains("marked draft or unlisted"));
    assert!(report.contains("partial or hidden document excluded"));
    assert!(!out.join("01-guide/03-Guides/draft.mdx").exists());
    assert!(!out.join("01-guide/_partial.mdx").exists());
    assert_eq!(
        fs::read_to_string(source.join("docs/03-Guides/_category_.json")).unwrap(),
        category
    );
    let body = fs::read_to_string(out.join("01-guide/03-Guides/index.mdx")).unwrap();
    assert!(body.contains("[Start](</guide/guides/start>)"));
}

#[test]
fn slice_order_is_local_and_repeated_documents_are_written_once() {
    let temp = tempfile::tempdir().unwrap();
    let source = temp.path().join("source");
    let out = temp.path().join("out");
    fixture(
        &source,
        "['before', {type:'category', label:'Manual... `require()`', items:[{type:'autogenerated', dirName:'a'}, 'middle', {type:'autogenerated', dirName:'b'}]}, 'after', {type:'autogenerated', dirName:'a'}, {type:'link',label:'External',href:'https://example.com'}]",
    );
    for file in [
        "before.md",
        "middle.md",
        "after.md",
        "a/10-Last.md",
        "a/02-First.md",
        "b/00-Early.md",
        "b2/other.md",
        "orphan.md",
    ] {
        write(&source, &format!("docs/{file}"), "# Page");
    }
    let report = success(convert(&source, &out, false));
    let nav = nav(&out);
    assert_eq!(
        names(&nav),
        [
            "before",
            "Manual... `require()`",
            "after",
            "a/02-First",
            "a/10-Last"
        ]
    );
    assert_eq!(
        names(&nav[1]["items"]),
        ["a/02-First", "a/10-Last", "middle", "b/00-Early"]
    );
    assert_eq!(fs::read_dir(out.join("01-guide/a")).unwrap().count(), 2);
    assert!(report.contains("orphan.md"));
    assert!(report.contains("external link"));
    assert!(!out.join("01-guide/b2/other.mdx").exists());
    assert!(!out.join("01-guide/orphan.mdx").exists());
}

#[test]
fn category_index_links_inherit_metadata_and_explicit_null_disables_conventions() {
    let temp = tempfile::tempdir().unwrap();
    let source = temp.path().join("source");
    let out = temp.path().join("out");
    fixture(&source, "[{type:'autogenerated',dirName:'.'}]");
    write(
        &source,
        "docs/a/landing.md",
        "---\nid: intro\nsidebar_label: Inherited\nsidebar_position: -2\n---\n# Page",
    );
    write(&source, "docs/a/child.md", "# Child");
    write(
        &source,
        "docs/a/_category_.json",
        r#"{"link":{"type":"doc","id":"intro"}}"#,
    );
    write(
        &source,
        "docs/b/index.md",
        "---\nsidebar_label: Not inherited\nsidebar_position: -10\n---\n# Index",
    );
    write(&source, "docs/b/_category_.yml", "link: null\n");
    write(&source, "docs/c/index.md", "# Preserved index");
    write(
        &source,
        "docs/c/_category_.yaml",
        "link:\n  type: generated-index\n  title: Source landing\n  slug: /source-only\n",
    );
    write(&source, "docs/d/a.md", "# Page");
    write(
        &source,
        "docs/d/draft.md",
        "---\ndraft: true\nid: omitted\n---\n# Draft",
    );
    write(
        &source,
        "docs/d/_category_.json",
        r#"{"link":{"type":"doc","id":"omitted"}}"#,
    );
    let report = success(convert(&source, &out, false));
    let nav = nav(&out);
    assert_eq!(names(&nav), ["Inherited", "b", "c", "d"]);
    assert_eq!(nav[0]["items"][0]["page"], "a/landing");
    assert_eq!(names(&nav[0]["items"]), ["Inherited", "a/child"]);
    assert_eq!(nav[1]["items"][0]["page"], "b/index");
    assert_eq!(names(&nav[2]["items"]), ["Source landing", "c/index"]);
    assert_eq!(names(&nav[3]["items"]), ["d/a"]);
    assert!(!report.contains("category link fields not mapped: slug"));
    let page: Value = serde_yaml_ng::from_str(
        fs::read_to_string(out.join("01-guide/category/c/index.mdx"))
            .unwrap()
            .split("---")
            .nth(1)
            .unwrap(),
    )
    .unwrap();
    assert_eq!(page["route"], "/guide/source-only");
    assert!(out.join("01-guide/category/c/index.mdx").exists());
    assert!(!out.join("01-guide/d/draft.mdx").exists());
}

#[test]
fn automatic_paths_do_not_depend_on_legacy_id_aliases_and_disabled_prefixes_keep_position_rules() {
    let temp = tempfile::tempdir().unwrap();
    let source = temp.path().join("source");
    let out = temp.path().join("out");
    fixture(&source, "[{type:'autogenerated',dirName:'.'}]");
    write(&source, "docs/file.md", "---\nid: other\n---\n# File");
    write(&source, "docs/other.md", "---\nid: another\n---\n# Other");
    write(
        &source,
        "docs/01-Keep.md",
        "---\nparse_number_prefixes: false\n---\n# Keep",
    );
    write(&source, "docs/02-First.md", "# First");
    write(
        &source,
        "docs/03-Second.md",
        "---\nparse_number_prefixes: false\nsidebar_position: 2.5\n---\n# Second",
    );
    success(convert(&source, &out, false));
    assert_eq!(
        names(&nav(&out)),
        ["02-First", "03-Second", "01-Keep", "file", "other"]
    );
}

#[test]
fn unsafe_and_missing_autogenerated_directories_fail_before_output() {
    for directory in [
        "../outside",
        "/absolute",
        "a\\b",
        "missing",
        "page.md",
        "a/../b",
        ".git",
        "",
    ] {
        let temp = tempfile::tempdir().unwrap();
        let source = temp.path().join("source");
        let out = temp.path().join("out");
        let value = serde_json::json!([{"type":"autogenerated", "dirName":directory}]);
        fixture(&source, &value.to_string());
        write(&source, "docs/page.md", "# Keep");
        let result = convert(&source, &out, false);
        assert!(!result.status.success(), "{directory}");
        assert!(!out.exists());
        assert_eq!(
            fs::read_to_string(source.join("docs/page.md")).unwrap(),
            "# Keep"
        );
    }
}

#[test]
fn invalid_category_metadata_and_positions_fail_before_output() {
    for metadata in [
        "[]",
        "label: 7",
        "label: ''",
        "position: '2'",
        "position: .nan",
        "position: .inf",
        "link: []",
        "link: {type: doc}",
        "link: {type: doc, id: missing}",
        "link: {type: unknown}",
        "label: A\nlabel: B",
        "position: [",
    ] {
        let temp = tempfile::tempdir().unwrap();
        let source = temp.path().join("source");
        let out = temp.path().join("out");
        fixture(&source, "[{type:'autogenerated',dirName:'.'}]");
        write(&source, "docs/group/page.md", "# Keep");
        write(&source, "docs/group/_category_.yaml", metadata);
        let result = convert(&source, &out, false);
        assert!(!result.status.success(), "{metadata}");
        assert!(String::from_utf8_lossy(&result.stderr).contains("category"));
        assert!(!out.exists());
        assert_eq!(
            fs::read_to_string(source.join("docs/group/_category_.yaml")).unwrap(),
            metadata
        );
    }
    for value in ["'2'", ".nan", ".inf", "[]", "true"] {
        let temp = tempfile::tempdir().unwrap();
        let source = temp.path().join("source");
        let out = temp.path().join("out");
        fixture(&source, "[{type:'autogenerated',dirName:'.'}]");
        write(
            &source,
            "docs/page.md",
            &format!("---\nsidebar_position: {value}\n---\n# Keep"),
        );
        let result = convert(&source, &out, false);
        assert!(!result.status.success(), "{value}");
        assert!(
            String::from_utf8_lossy(&result.stderr)
                .contains("sidebar_position must be a finite number")
        );
        assert!(!out.exists());
    }
}

#[test]
fn duplicate_category_files_are_rejected_and_empty_slices_are_reported() {
    let temp = tempfile::tempdir().unwrap();
    let source = temp.path().join("source");
    let out = temp.path().join("out");
    fixture(&source, "[{type:'autogenerated',dirName:'.'}]");
    write(&source, "docs/group/page.md", "# Keep");
    write(&source, "docs/group/_category_.json", "{}");
    write(&source, "docs/group/_category_.yml", "{}");
    let result = convert(&source, &out, false);
    assert!(!result.status.success());
    assert!(String::from_utf8_lossy(&result.stderr).contains("multiple category files"));
    assert!(!out.exists());
    fs::create_dir(source.join("docs/empty")).unwrap();
    fixture(&source, "[{type:'autogenerated',dirName:'empty'}]");
    let report = success(convert(&source, &out, true));
    assert!(report.contains("autogenerated sidebar slice has no eligible documents"));
    assert!(!out.exists());
}

#[test]
fn dry_run_lists_the_expanded_plan_without_writing() {
    let temp = tempfile::tempdir().unwrap();
    let source = temp.path().join("source");
    let out = temp.path().join("out");
    fixture(&source, "[{type:'autogenerated',dirName:'.'}]");
    write(&source, "docs/guide/index.md", "# Keep");
    let report = success(convert(&source, &out, true));
    assert!(report.contains("01-guide/guide/index.mdx"));
    assert!(!out.exists());
    assert_eq!(
        fs::read_to_string(source.join("docs/guide/index.md")).unwrap(),
        "# Keep"
    );
}

#[cfg(unix)]
#[test]
fn linked_category_files_are_rejected_before_reading_or_writing() {
    let temp = tempfile::tempdir().unwrap();
    let source = temp.path().join("source");
    let out = temp.path().join("out");
    fixture(&source, "[{type:'autogenerated',dirName:'.'}]");
    write(&source, "docs/guide/page.md", "# Keep");
    write(temp.path(), "outside.json", "private invalid JSON");
    std::os::unix::fs::symlink(
        temp.path().join("outside.json"),
        source.join("docs/guide/_category_.json"),
    )
    .unwrap();
    let result = convert(&source, &out, false);
    assert!(!result.status.success());
    assert!(String::from_utf8_lossy(&result.stderr).contains("symbolic links and junctions"));
    assert!(!out.exists());
    assert_eq!(
        fs::read_to_string(temp.path().join("outside.json")).unwrap(),
        "private invalid JSON"
    );
}
